// switch example
switch (value) {
    case 1:
        // code
        break;
    case 2:
        // code
        break;
    default:
        // code
}

// equivalent if-else
if (value == 1) {
    // code
} else if (value == 2) {
    // code
} else {
    // code
}

switch (dayOfWeek) {
    case MONDAY:
    case TUESDAY:
    case WEDNESDAY:
    case THURSDAY:
    case FRIDAY:
        System.out.println("It's a weekday");
        break;
    case SATURDAY:
    case SUNDAY:
        System.out.println("It's the weekend");
        break;
}

String fruit = "apple";
switch (fruit) {
    case "apple":
        System.out.println("It's an apple");
        break;
    case "banana":
        System.out.println("It's a banana");
        break;
    default:
        System.out.println("Unknown fruit");
}

// Potentially more efficient for many cases
switch (value) {
    case 1: // O(1) time complexity
    case 2:
    // ... many more cases
    default:
}

// Less efficient for many cases
if (value == 1) { // O(n) time complexity in worst case
} else if (value == 2) {
    // ... many more else-if statements
} else {
}
